// Checks the translations in apps/web/src/locales.
//
//   pnpm i18n --check      report; exit 1 on errors
//   pnpm i18n --write      also update the status table in TRANSLATING.md
//
// Errors (exit 1): invalid JSON; English keys the code doesn't use; keys the
// code uses that English doesn't have; a translation whose {{placeholders}}
// or <tags> differ from English.
// Warnings only: missing or unused keys in a translation, so a half-done
// Weblate translation never breaks CI.
// fields.json is generated by `pnpm schemas` (see its own --check); here it
// is only compared per language.
// Runs on plain Node (built-in type stripping), so only erasable TypeScript here.

import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import {
	compareLanguage,
	flatten,
	isUsed,
	parseTranslations,
	replaceStatus,
	type StatusRow,
	statusTable,
	usedKeys,
} from "./i18n-lib.ts";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const LOCALES = join(ROOT, "apps/web/src/locales");
const SOURCE_DIR = join(ROOT, "apps/web/src");
const TRANSLATING = join(ROOT, "TRANSLATING.md");
const SOURCE = "en";
const NAMESPACES = ["app", "fields"] as const;

const errors: string[] = [];
const warnings: string[] = [];

function sourceFiles(dir: string): string[] {
	return readdirSync(dir).flatMap((name) => {
		const path = join(dir, name);
		if (statSync(path).isDirectory())
			return name === "locales" ? [] : sourceFiles(path);
		return /\.tsx?$/.test(name) ? [path] : [];
	});
}

function load(language: string, namespace: string): Map<string, string> | null {
	const path = join(LOCALES, language, `${namespace}.json`);
	let text: string;
	try {
		text = readFileSync(path, "utf8");
	} catch {
		return null;
	}
	const parsed = parseTranslations(text);
	if (!parsed.ok) {
		errors.push(`${relative(ROOT, path)}: invalid JSON (${parsed.error})`);
		return null;
	}
	return flatten(parsed.value);
}

function languageName(code: string): string {
	const english = new Intl.DisplayNames(["en"], { type: "language" }).of(code);
	let own: string | undefined;
	try {
		own = new Intl.DisplayNames([code], { type: "language" }).of(code);
	} catch {
		own = undefined;
	}
	if (!english || english === code) return code;
	const native = own
		? own.charAt(0).toLocaleUpperCase(code) + own.slice(1)
		: english;
	return native === english ? english : `${english} (${native})`;
}

function list(keys: readonly string[]): string {
	const shown = keys.slice(0, 8).join(", ");
	return keys.length > 8 ? `${shown}, … (${keys.length} in total)` : shown;
}

function main(): void {
	const args = process.argv.slice(2);
	const source = new Map(NAMESPACES.map((ns) => [ns, load(SOURCE, ns)]));
	const app = source.get("app");
	if (!app) {
		console.error("✗ apps/web/src/locales/en/app.json is missing or invalid");
		for (const error of errors) console.error(`✗ ${error}`);
		process.exit(1);
	}

	// The source and the code must match exactly.
	const used = usedKeys(
		sourceFiles(SOURCE_DIR).map((file) => readFileSync(file, "utf8")),
	);
	const notInCode = [...app.keys()].filter((key) => !isUsed(key, used));
	if (notInCode.length > 0) {
		errors.push(
			`en/app.json has keys the code doesn't use: ${list(notInCode)}`,
		);
	}
	const fields = source.get("fields");
	const known = (key: string) => {
		const [namespace, rest] = key.includes(":")
			? key.split(":", 2)
			: ["app", key];
		const flat = namespace === "fields" ? fields : app;
		return (
			flat?.has(rest ?? "") === true ||
			flat?.has(`${rest}_other`) === true ||
			flat?.has(`${rest}_one`) === true
		);
	};
	const notInSource = [...used.called].filter((key) => !known(key));
	if (notInSource.length > 0) {
		errors.push(
			`the code uses keys en/app.json doesn't have: ${list(notInSource)}`,
		);
	}

	// Every translation against English.
	const languages = readdirSync(LOCALES)
		.filter(
			(name) => name !== SOURCE && statSync(join(LOCALES, name)).isDirectory(),
		)
		.sort();
	const rows: StatusRow[] = [
		{ name: languageName(SOURCE), code: SOURCE, translated: 1, total: 1 },
	];
	for (const folder of languages) {
		const code = folder.replaceAll("_", "-");
		let translated = 0;
		let total = 0;
		for (const namespace of NAMESPACES) {
			const english = source.get(namespace);
			if (!english) continue;
			const target = load(folder, namespace) ?? new Map<string, string>();
			const report = compareLanguage(english, target, code);
			translated += report.translated;
			total += report.total;
			const file = `${folder}/${namespace}.json`;
			if (report.placeholderErrors.length > 0) {
				errors.push(
					`${file}: placeholders or tags differ from English in ${list(report.placeholderErrors)}`,
				);
			}
			if (report.missing.length > 0) {
				warnings.push(
					`${file}: ${report.missing.length} missing: ${list(report.missing)}`,
				);
			}
			if (report.unused.length > 0) {
				warnings.push(
					`${file}: ${report.unused.length} unused: ${list(report.unused)}`,
				);
			}
		}
		rows.push({ name: languageName(code), code, translated, total });
	}

	const table = statusTable(rows);
	console.log(table);
	console.log("");
	for (const warning of warnings) console.warn(`! ${warning}`);
	for (const error of errors) console.error(`✗ ${error}`);

	if (args.includes("--write")) {
		const markdown = readFileSync(TRANSLATING, "utf8");
		const next = replaceStatus(markdown, table);
		if (next === null) {
			console.error("✗ TRANSLATING.md has no i18n-status markers");
			process.exit(1);
		}
		if (next !== markdown) writeFileSync(TRANSLATING, next);
		console.log("Updated the status table in TRANSLATING.md.");
	}
	if (errors.length > 0) process.exit(1);
	console.log(
		`✓ Translations OK (${languages.length} language${languages.length === 1 ? "" : "s"} besides English, ${warnings.length} warning${warnings.length === 1 ? "" : "s"}).`,
	);
}

main();
